<script setup>
import {computed,reactive,ref,watch} from 'vue';
import {Head,router} from '@inertiajs/vue3';
import AuthenticatedLayout from '@/Layouts/AuthenticatedLayout.vue';
import {useFamilyCopy} from '@/lib/family';
const p=defineProps({rooms:Array,classroomId:Number,date:String,today:String,canReplace:Boolean,children:Array});
const {l,t}=useFamilyCopy();const room=ref(p.classroomId||''),day=ref(p.date),kind=ref('care'),selected=ref([]),replace=ref(false),preview=ref(null),busy=ref(false),error=ref(''),success=ref(''),confirmed=ref(false);
const fields=reactive({meals:'',naps:'',mood:'',activities:'',notes:''});
const labels={meals:'Meals',naps:'Naps',mood:'Mood',activities:'Activities',notes:'Notes',check_in_at:'Arrival'};
const limits={meals:500,naps:500,mood:100,activities:1000,notes:2000};
const eligible=computed(()=>p.children.filter(c=>kind.value!=='checkin'||!c.checked_out));
watch([selected,kind,replace,fields],()=>{preview.value=null;confirmed.value=false;error.value='';},{deep:true});
watch(kind,()=>{selected.value=selected.value.filter(id=>eligible.value.some(c=>c.id===id));});
function all(e){selected.value=e.target.checked?eligible.value.map(c=>c.id):[];}
function errorText(e){const status=e.response?.status;if(status===409)return l('تغيرت السجلات بعد المعاينة. أعد المعاينة وراجع التغييرات قبل الحفظ.','Records changed after the preview. Review a new preview before saving.');if(status===410)return l('انتهت صلاحية المعاينة. أنشئ معاينة جديدة قبل الحفظ.','This preview expired. Review a fresh preview.');if(status===423)return l('مساحة الحضانة للعرض فقط حالياً. راجع الإدارة لتفعيل الحفظ.','The nursery is currently read-only. Contact management before saving.');if(status===403)return l('لا تملك صلاحية هذا الإجراء. راجع إدارة الحضانة.','You do not have permission for this action. Contact nursery management.');return Object.values(e.response?.data?.errors||{}).flat().join(' ')||e.response?.data?.message||l('تعذر إتمام الطلب. حاول مجدداً.','Request unavailable. Try again.');}
function load(){router.get('/classroom-batches',{classroom_id:room.value,date:day.value},{preserveState:false});}
async function review(){error.value='';success.value='';preview.value=null;confirmed.value=false;busy.value=true;try{const {data}=await window.axios.post('/classroom-batches/preview',{classroom_id:p.classroomId,date:p.date,kind:kind.value,child_ids:selected.value,fields:{...fields},replace_existing:replace.value});preview.value=data;}catch(e){error.value=errorText(e);}finally{busy.value=false;}}
async function save(){if(!confirmed.value||!preview.value)return;busy.value=true;error.value='';try{const{data}=await window.axios.post(`/classroom-batches/${preview.value.id}/apply`,{confirmed:true});success.value=l(`تم تحديث ${data.changed_count} سجل. بقي ${data.unchanged_count} دون تغيير.`,`Updated ${data.changed_count} records. ${data.unchanged_count} unchanged.`);preview.value=null;selected.value=[];confirmed.value=false;router.reload({only:['children']});}catch(e){error.value=errorText(e);preview.value=null;confirmed.value=false;}finally{busy.value=false;}}
</script>
<template><Head :title="l('تسجيل الفصل','Classroom batch')"/><AuthenticatedLayout><div class="family-main">
<header class="family-heading"><p class="eyebrow">{{l('رعاية مشتركة، ومراجعة فردية','Shared care, individual review')}}</p><h1>{{l('الفصل، بخطوة مدروسة','A considered step for the classroom')}}</h1><p class="family-muted">{{l('اختر الأطفال والتحديث، ثم راجع التغييرات قبل الحفظ. الاستلام يبقى إجراءً فردياً بعد التحقق من الهوية.','Choose children and an update, then review the changes before saving. Pickup stays an individual identity-checked handover.')}}</p></header>
<form class="family-card family-range" @submit.prevent="load"><label>{{l('الفصل','Classroom')}}<select v-model="room" required class="search-field"><option value="" disabled>{{l('اختر فصلاً','Choose a classroom')}}</option><option v-for="r in rooms" :key="r.id" :value="r.id">{{r.name}}</option></select></label><label>{{l('التاريخ','Date')}}<input v-model="day" type="date" :max="today" required/></label><button class="family-primary" :disabled="busy">{{l('عرض الفصل','Load classroom')}}</button></form>
<p v-if="error" role="alert" class="family-card family-error mt-5">{{error}}</p><p v-if="success" role="status" class="family-card family-success mt-5">{{success}}</p>
<div v-if="classroomId" class="family-manage-grid mt-6"><section class="family-card"><h2>{{l('الأطفال المحددون','Selected children')}} · {{selected.length}} / {{children.length}}</h2><p class="family-muted">{{l('لا يسجل هذا الاختيار حضوراً أو يومية حتى تراجع وتؤكد الحفظ. الحد ١٠٠ طفل لكل دفعة.','Selection alone records nothing. Review and confirm to save. Up to 100 children per batch.')}}</p><label class="batch-choice"><input type="checkbox" :checked="selected.length===eligible.length&&eligible.length>0" @change="all" :disabled="!eligible.length||busy"/>{{l('اختيار كل المتاحين','Select all eligible')}}</label><label v-for="c in children" :key="c.id" class="batch-choice"><input v-model="selected" type="checkbox" :value="c.id" :disabled="busy||(kind==='checkin'&&c.checked_out)"/><span><strong>{{c.name}}</strong><small class="block family-muted">{{kind==='care'?(c.has_log?l('توجد يومية سابقة','Existing care entry'):l('بدون يومية','No care entry')):(c.checked_out?l('تم الاستلام، راجع فردياً','Already left, review individually'):c.checked_in?l('الحضور مسجل بالفعل','Arrival already recorded'):l('لم يسجل الحضور','Arrival not recorded'))}}</small></span></label><p v-if="!children.length" class="family-muted">{{l('لا يوجد أطفال نشطون بهذا الفصل.','No active children in this classroom.')}}</p></section>
<section class="family-card"><form class="family-form !mt-0" @submit.prevent="review"><label>{{l('الإجراء','Action')}}<select v-model="kind" :disabled="busy"><option value="care">{{l('تحديث رعاية مشترك','Shared care update')}}</option><option value="checkin">{{l('تسجيل وصول الموجودين الآن','Record children present now')}}</option></select></label><template v-if="kind==='care'"><p class="family-muted">{{l('الحقول الفارغة لا تمحو بيانات. تبقى القيم السابقة افتراضياً، وتملأ الحقول الخالية فقط. أي يومية تتغير ستحتاج مراجعة جديدة قبل مشاركتها مع الأسرة.','Empty fields never erase data. Existing values stay by default; only missing values are filled. Changed care entries need fresh review before family sharing.')}}</p><label v-for="(label,key) in labels" :key="key" v-show="key!=='check_in_at'">{{t(label)}}<textarea v-if="key!=='check_in_at'" v-model="fields[key]" rows="2" :maxlength="limits[key]" :disabled="busy"/></label><label v-if="canReplace" class="check"><input v-model="replace" type="checkbox" :disabled="busy"/>{{l('بصفتي مديراً، أريد استبدال القيم الموجودة في الحقول التي أدخلتها. سأراجع كل تغيير قبل الحفظ.','As a manager, replace existing values for fields I entered. I will review each change before saving.')}}</label></template><p v-else class="family-muted">{{l('لليوم الحالي فقط. تأكد بنفسك من وجود الأطفال المختارين الآن. لا يعيد هذا حضور طفل تم استلامه، ولا يغيّر اليوميات أو الرسوم.','Today only. Personally confirm the selected children are present now. This does not reopen attendance after pickup or change care or fees.')}}</p><button class="family-primary" :disabled="busy||!selected.length||selected.length>100||(kind==='care'&&Object.values(fields).every(v=>!v.trim()))||(kind==='checkin'&&date!==today)">{{l('معاينة التغييرات','Preview changes')}}</button></form></section></div>
<section v-if="preview" class="family-card mt-6"><h2>{{l('راجع قبل الحفظ','Review before saving')}}</h2><p class="family-muted">{{l(`سيتغير ${preview.changed_count} سجل. دون تغيير: ${preview.unchanged_count}. المعاينة صالحة لعشر دقائق وتتوقف إذا تغيرت السجلات.`,`Will update ${preview.changed_count} records. Unchanged: ${preview.unchanged_count}. Preview lasts ten minutes and stops if records change.`)}}</p><article v-for="row in preview.rows" :key="row.id" class="family-ledger"><strong>{{row.name}}</strong><p v-if="row.unchanged" class="family-muted">{{l('لا تغيير. القيم السابقة محفوظة.','No change. Existing values retained.')}}</p><div v-for="v in row.changes" :key="v.field" class="mt-3"><b>{{t(labels[v.field])}}</b><template v-if="kind==='care'"><p class="family-copy family-muted">{{l('قبل','Before')}}: {{v.before||l('فارغ','Empty')}}</p><p class="family-copy">{{l('بعد','After')}}: {{v.after}}</p></template><p v-else>{{l('سيسجل الوصول في توقيت الحضانة عند التأكيد.','Arrival will be recorded in nursery time when confirmed.')}}</p></div></article><label class="batch-choice"><input v-model="confirmed" type="checkbox" :disabled="busy"/>{{kind==='care'?l('راجعت الأطفال والتغييرات الموضحة، وأوافق على حفظها.','I reviewed the children and displayed changes and confirm saving.'):l('تحققت فعلياً أن كل طفل مختار موجود الآن، وأوافق على تسجيل وصولهم.','I personally confirmed every selected child is present now and approve recording arrival.')}}</label><button class="family-primary w-full" :disabled="busy||!confirmed||!preview.changed_count" @click="save">{{l('تأكيد وحفظ الدفعة','Confirm and save batch')}}</button></section>
</div></AuthenticatedLayout></template>
<style scoped>.batch-choice{display:flex;align-items:flex-start;gap:12px;padding:16px 0;line-height:1.9;font-size:14px}.batch-choice input{flex-shrink:0;margin-top:6px;width:18px;height:18px}.family-range select{min-height:46px;min-width:0;width:100%}.batch-choice:has(input:disabled){opacity:.65}</style>
